(56, 1, '2017-12-13 19:52:24', '2017-12-13 16:52:24', '<div class=\"row\">\r\n											<div class=\"col-md-2 col-sm-3\">\r\n											<img src=\"http://cmd-lyubertsy.ru/wp-content/themes/cmd/images/boldyreva.jpg\">																			\r\n											</div>	\r\n											\r\n											<div class=\"col-md-9 offset-md-1 col-sm-9\">\r\n											<h1>Ольга Валерьевна Болдырева</h1>		\r\n											<h3>Акушер-гинеколог, гинеколог, кольпоскопия, УЗИ диагностика	</h3>\r\n											<a href=\"/vrachi/boldyreva/\">Подробнее о враче</a>		\r\n											</div>												\r\n										</div>\r\n									<h1 id=\"raspisanie\">Расписание</h1>\r\n										<div class=\"row\">\r\n											<div class=\"col-md-3 border text-center\">\r\n											Вторник 8.30-15.30																		\r\n											</div>	\r\n											\r\n											<div class=\"col-md-3 border text-center\">\r\n											Среда 8.30-15.30																		\r\n											</div>	\r\n\r\n											<div class=\"col-md-3 border text-center\">\r\n											Четверг 8.30-15.30																		\r\n											</div>	\r\n\r\n											<div class=\"col-md-3 border text-center\">\r\n											Суббота 9.00-16.00																		\r\n											</div>												\r\n											\r\n										</div>', 'Врачи', '', 'publish', 'closed', 'closed', '', 'vrachi', '', '', '2017-12-13 20:01:46', '2017-12-13 17:01:46', '', 0, 'http://cmd-lyubertsy.ru/?page_id=56', 0, 'page', '', 0),
(15, 1, '2017-12-13 07:46:02', '2017-12-13 04:46:02', '', 'Наши услуги', '', 'inherit', 'closed', 'closed', '', '14-revision-v1', '', '', '2017-12-13 07:46:02', '2017-12-13 04:46:02', '', 14, 'http://cmd-lyubertsy.ru/2017/12/13/14-revision-v1/', 0, 'revision', '', 0),
(16, 1, '2017-12-13 07:46:27', '2017-12-13 04:46:27', '<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Ультразвуковое исследование</b></span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Ультразвуковое исследование</b></span> <span style=\"font-family: Arial, serif;\"><b>(УЗИ, сонография, ультрасонография, эхография)</b></span><span style=\"font-family: Arial, serif;\"> – современный аппаратный диагностический метод, основанный на регистрации и визуализации изменений ульразвукового сигнала, отражаемого от различных органов и тканей.</span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">В процессе исследования используется специальный датчик, одновременно излучающий ультразвуковые волны и принимающий отраженный сигнал – «эхо». При прохождении через различные по плотности ткани, границы органов, данный сигнал претерпевает определенные изменения, которые и фиксируются датчиком. Полученная информация перерабатывается компьютером в визуальное изображение на мониторе.</span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Преимущества метода</b></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">высокая информативность</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">относительно невысокая стоимость;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">неинвазивность (не требует нарушения целостности тканей);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">безболезненность;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">безопасность</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">возможность изучения как структуры, так и функции органов</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">возможность многократного повторения исследования без вреда для пациента.</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Перечисленные преимущества позволяют использовать данный метод для проведения скрининговых профилактических исследований с целью ранней диагностики, для уточнения предположительного диагноза, а также для динамического наблюдения за развитием заболевания, контроля эффективности лечения. УЗИ широко используется при ведении беременности, обследовании детей грудного возраста.</span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Ультразвуковым методом можно исследовать следующие органы и системы</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">органы брюшной полости (печень, желчный пузырь и желчевыводящие протоки, поджелудочная железа);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">мочевыделительная система (почки, мочеточники, мочевой пузырь);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">органы репродуктивной системы у женщин и мужчин (матка и яичники, фаллопиевы трубы, предстательная железа);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">молочные железы;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">щитовидная железа;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">головной мозг;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">сердце и сосуды;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">мягкие ткани.</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">С помощью ультразвука специалист получает, в первую очередь, информацию о строении органа</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">расположение, контуры, размер, соотношение анатомических структур, наличие аномалий</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">плотность, однородность тканей, наличие включений, конкрементов (камней);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">объемные образования (опухоли, кисты, абсцессы и др.).</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Кроме того, отдельные виды исследований с использованием ультразвука позволяют также оценить функцию изучаемого органа, например</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">при УЗИ сердца (эхокардиография) оцениваются особенности гемодинамики, полноценность работы сердечных клапанов, сократительная способность миокарда</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">ультразвуковое исследование сосудов позволяет не только обнаружить аневризмы, атеросклеротические бляшки и тромбы, но также (при использовании допплер-эффекта) измерить скорость, объем и др. параметры кровотока</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">под контролем УЗИ выполняются функциональные пробы – например, для исследования моторной функции желчного пузыря (пробный завтрак) и др.</span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Особенно востребован метод УЗИ в акушерстве и гинекологии</b></span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"><b>:</b></span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">диагностика причин бесплодия;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">диагностика беременности (в т.ч. внематочной), определение ее срока;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">наблюдение за течением беременности, выявление угрозы выкидыша и др. видов патологии;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">определение расположения плода в матке, выявление возможных аномалий развития, выяснение пола будущего ребенка (на современном этапе можно получать 3D</span></span><span style=\"font-family: Arial, serif;\">-изображение высокой четкости)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">раннее обнаружение новообразований в матке и яичниках, выявление эндометриоза, фибромиом, кист и пр.;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">выполнение некоторых лечебно-диагностических манипуляций под контролем УЗИ повышает их эффективность и безопасность.</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"><b>Дуплексное сканирование вен и артерий</b></span></span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"> – отдельный диагностический метод с использованием возможностей ультразвука. Современный вариант данного исследования называется цветовым дуплексным сканированием (ЦДС), или триплексным сканированием, т.к. в него входят три составляющие:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">подробная визуализация сосудов;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">допплерография (определение скорости кровотока и др. его параметров на основе допплер-эффекта – изменения частоты отраженного сигнала в зависимости от скоросте движения);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">цветовое картирование – наглядное обозначение цветом особенностей гемодинамики на разных участках сосудистого русла (направление тока крови, турбулентность и т.д.).</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">Преимуществами метода, который уже стал “золотым стандартом”, являются безопасность, неинвазивность, высокая информативность и быстрота выполнения процедуры. С помощью ЦДС можно изучить расположение сосудов, их извитость, определить наличие сосудистых аномалий, выпячиваний или сужений, измерить толщину стенки и ширину просвета сосуда, обнаружить препятствия, мешающие свободному движению крови (атеросклеротические бляшки, тромбы). При исследовании вен определяется также состоятельность венозных клапанов.</span></span></p>\r\n<p align=\"JUSTIFY\"><a name=\"_GoBack\"></a><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">В зависимости от назначения врача исследуется определенная группа сосудов</span></span><span style=\"font-family: Arial, serif;\">.</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"> Например, ЦДС брахиоцефальных артерий (сосудов головы и </span></span><span style=\"font-family: Arial, serif;\">шеи</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">) – при симптомах нарушения мозгового кровообращения; ЦДС вен нижних конечностей – при подозрении на венозную недостаточность, варикозное расширение вен, флеботромбоз.</span></span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Подготовка пациента к проведению ультразвукового исследования</b></span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Специальная подготовка требуется лишь при некоторых видах УЗИ</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">на исследование органов мочевыделительной системы, предстательной железы пациенту необходимо приходить с максимально наполненным мочевым пузырем (выпить не менее 1 литра воды за час до исследования и не мочиться)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">так же следует поступить перед прохождением УЗИ органов малого таза (матка, яичники), если исследование предполагается проводить через переднюю брюшную стенку (наружным датчиком)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">особенно тщательно необходимо подготовиться к плановому УЗИ органов брюшной полости – значительное скопление газов в кишечнике крайне затрудняет исследование, поэтому за три дня до процедуры рекомендуется исключить из рациона бобовые, капусту, черный хлеб, молоко и др. продукты, усиливающие газообразование, принимать ферментные препараты, адсорбенты (активированный уголь) или др. средства против метеоризма, последний прием пищи должен быть не позднее 7 часов вечера накануне, исследование проводится натощак</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">плановое УЗИ молочных желез желательно проходить на 5-8 день менструального цикла, гинекологическое – в зависимости от цели исследования (для выявления эндометриоза – накануне менструации, при изучении процесса созревания фолликулов – на 5-й, 9-й и 14-17 дни цикла, в других случаях – на 7-10 день цикла).</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><a name=\"section_4\"></a><a name=\"aswift_2_expand\"></a><a name=\"aswift_2_anchor\"></a><a name=\"section_5\"></a> <span style=\"font-family: Arial, serif;\">Несмотря на высокую информативность метода, результаты УЗИ должны трактоваться специалистом в комплексе с результатами других исследований и клинической картиной заболевания.</span></p>\r\n\r\n<table border=\"1\" cellspacing=\"0\" width=\"100%\"><tr><td>	Узи органов малого таза - трансабдоминально<p> - трансвагинально</p></td><td><p>1500 руб.</p><p>1600 руб.</p></td></tr><tr><td>	УЗИ в 1 триместре беременности (до 14 недель)</td><td><p>1700 руб.</p></td></tr><tr><td>	УЗИ в 1 триместре беременности при многоплодной беременности (до 14 недель)</td><td><p>2700 руб.</p></td></tr><tr><td>	УЗИ плода во втором триместре ( 14- 28 недель)</td><td><p>2400 руб.</p></td></tr><tr><td>	УЗИ плода во втором триместре при многоплодной беременности ( 14- 28 недель)</td><td><p>3500 руб.</p></td></tr><tr><td>	УЗИ плода в третьем триместре ( с 29 недели)</td><td><p>2400 руб.</p></td></tr><tr><td>	УЗИ плода в третьем триместре при многоплодной беременности ( с 29 недели)</td><td><p>3700 руб.</p></td></tr><tr><td>	УЗИ определение пола</td><td><p>1200 руб.</p></td></tr><tr><td>	Допплеровское исследование кровотока во 2 –м , 3-мем триместре беременности</td><td><p>1400 руб.</p></td></tr><tr><td>	УЗИ скрининг овуляции</td><td><p>700 руб.</p></td></tr><tr><td>	Мониторинг созревания фолликула - 1 исследование (фолликулометрия)</td><td><p>800 руб.</p></td></tr><tr><td>	УЗИ шейки матки (цервикометрия)</td><td><p>800 руб.</p></td></tr><tr><td>	УЗИ лонного сочленения</td><td><p>800 руб.</p></td></tr><tr><td>	УЗИ щитовидной железы и региональных лимфоузлов (с ЦДК)</td><td><p>1300 руб.</p></td></tr><tr><td>	Комплексное УЗИ молочных желез и региональных лимфоузлов (с ЦДК)</td><td><p>1400 руб.</p></td></tr><tr><td>	УЗИ органов брюшной полости (печень, желчный пузырь, подж.железа, желчные протоки, селезенка)</td><td><p> 1800 руб.</p></td></tr><tr><td>	УЗИ органов брюшной полости + желчный пузырь с определением функции</td><td><p>2800 руб.</p></td></tr><tr><td>	УЗИ желчного пузыря с определением функции</td><td><p>1800 руб.</p></td></tr><tr><td>	УЗИ печени</td><td><p>800 руб.</p></td></tr><tr><td>	УЗИ брюшной полости + почки</td><td><p>2600 руб.</p></td></tr><tr><td>	УЗИ мочевыделительной системы (почки, мочеточники, мочевой пузырь, остаточная моча)</td><td><p>1800 руб.</p></td></tr><tr><td>	УЗИ почек, надпочечников с ЦДК</td><td><p>1200 руб.</p></td></tr><tr><td>	УЗИ почек</td><td><p>1300 руб.</p></td></tr><tr><td>	УЗИ почек и мочевого пузыря</td><td><p>1600 руб.</p></td></tr><tr><td>	УЗИ мочевого пузыря</td><td><p>800 руб.</p></td></tr><tr><td>	УЗИ мочевого пузыря с остаточной мочой</td><td><p>1200 руб.</p></td></tr><tr><td>	УЗИ лимфатических узлов (1 группа)</td><td><p>800 руб.</p></td></tr><tr><td>	УЗИ лимфатических узлов (3 группы)</td><td><p>2000 руб.</p></td></tr><tr><td>	УЗИ мягких тканей ( динамич. и поверх. структуры)</td><td><p>1200 руб.</p></td></tr></table> <h3>Услуги  процедурного  кабинета</h3>									\r\n', 'УЗИ', '', 'publish', 'closed', 'closed', '', 'uzi', '', '', '2017-12-13 20:10:07', '2017-12-13 17:10:07', '', 14, 'http://cmd-lyubertsy.ru/?page_id=16', 0, 'page', '', 0),
(17, 1, '2017-12-13 07:46:27', '2017-12-13 04:46:27', '', 'УЗИ', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2017-12-13 07:46:27', '2017-12-13 04:46:27', '', 16, 'http://cmd-lyubertsy.ru/2017/12/13/16-revision-v1/', 0, 'revision', '', 0),
(18, 1, '2017-12-13 08:14:49', '2017-12-13 05:14:49', '<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Ультразвуковое исследование</b></span></p>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Ультразвуковое исследование</b></span> <span style=\"font-family: Arial, serif;\"><b>(УЗИ, сонография, ультрасонография, эхография)</b></span><span style=\"font-family: Arial, serif;\"> – современный аппаратный диагностический метод, основанный на регистрации и визуализации изменений ульразвукового сигнала, отражаемого от различных органов и тканей.</span></p>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">В процессе исследования используется специальный датчик, одновременно излучающий ультразвуковые волны и принимающий отраженный сигнал – «эхо». При прохождении через различные по плотности ткани, границы органов, данный сигнал претерпевает определенные изменения, которые и фиксируются датчиком. Полученная информация перерабатывается компьютером в визуальное изображение на мониторе.</span></p>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Преимущества метода</b></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">высокая информативность</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">относительно невысокая стоимость;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">неинвазивность (не требует нарушения целостности тканей);</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">безболезненность;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">безопасность</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">возможность изучения как структуры, так и функции органов</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">возможность многократного повторения исследования без вреда для пациента.</span></span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Перечисленные преимущества позволяют использовать данный метод для проведения скрининговых профилактических исследований с целью ранней диагностики, для уточнения предположительного диагноза, а также для динамического наблюдения за развитием заболевания, контроля эффективности лечения. УЗИ широко используется при ведении беременности, обследовании детей грудного возраста.</span></p>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Ультразвуковым методом можно исследовать следующие органы и системы</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">органы брюшной полости (печень, желчный пузырь и желчевыводящие протоки, поджелудочная железа);</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">мочевыделительная система (почки, мочеточники, мочевой пузырь);</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">органы репродуктивной системы у женщин и мужчин (матка и яичники, фаллопиевы трубы, предстательная железа);</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">молочные железы;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">щитовидная железа;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">головной мозг;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">сердце и сосуды;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">мягкие ткани.</span></span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">С помощью ультразвука специалист получает, в первую очередь, информацию о строении органа</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">расположение, контуры, размер, соотношение анатомических структур, наличие аномалий</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">плотность, однородность тканей, наличие включений, конкрементов (камней);</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">объемные образования (опухоли, кисты, абсцессы и др.).</span></span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Кроме того, отдельные виды исследований с использованием ультразвука позволяют также оценить функцию изучаемого органа, например</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">при УЗИ сердца (эхокардиография) оцениваются особенности гемодинамики, полноценность работы сердечных клапанов, сократительная способность миокарда</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">ультразвуковое исследование сосудов позволяет не только обнаружить аневризмы, атеросклеротические бляшки и тромбы, но также (при использовании допплер-эффекта) измерить скорость, объем и др. параметры кровотока</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">под контролем УЗИ выполняются функциональные пробы – например, для исследования моторной функции желчного пузыря (пробный завтрак) и др.</span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Особенно востребован метод УЗИ в акушерстве и гинекологии</b></span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"><b>:</b></span></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">диагностика причин бесплодия;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">диагностика беременности (в т.ч. внематочной), определение ее срока;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">наблюдение за течением беременности, выявление угрозы выкидыша и др. видов патологии;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">определение расположения плода в матке, выявление возможных аномалий развития, выяснение пола будущего ребенка (на современном этапе можно получать 3D</span></span><span style=\"font-family: Arial, serif;\">-изображение высокой четкости)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">раннее обнаружение новообразований в матке и яичниках, выявление эндометриоза, фибромиом, кист и пр.;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">выполнение некоторых лечебно-диагностических манипуляций под контролем УЗИ повышает их эффективность и безопасность.</span></span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"><b>Дуплексное сканирование вен и артерий</b></span></span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"> – отдельный диагностический метод с использованием возможностей ультразвука. Современный вариант данного исследования называется цветовым дуплексным сканированием (ЦДС), или триплексным сканированием, т.к. в него входят три составляющие:</span></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">подробная визуализация сосудов;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">допплерография (определение скорости кровотока и др. его параметров на основе допплер-эффекта – изменения частоты отраженного сигнала в зависимости от скоросте движения);</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">цветовое картирование – наглядное обозначение цветом особенностей гемодинамики на разных участках сосудистого русла (направление тока крови, турбулентность и т.д.).</span></span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">Преимуществами метода, который уже стал “золотым стандартом”, являются безопасность, неинвазивность, высокая информативность и быстрота выполнения процедуры. С помощью ЦДС можно изучить расположение сосудов, их извитость, определить наличие сосудистых аномалий, выпячиваний или сужений, измерить толщину стенки и ширину просвета сосуда, обнаружить препятствия, мешающие свободному движению крови (атеросклеротические бляшки, тромбы). При исследовании вен определяется также состоятельность венозных клапанов.</span></span></p>\n<p align=\"JUSTIFY\"><a name=\"_GoBack\"></a><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">В зависимости от назначения врача исследуется определенная группа сосудов</span></span><span style=\"font-family: Arial, serif;\">.</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"> Например, ЦДС брахиоцефальных артерий (сосудов головы и </span></span><span style=\"font-family: Arial, serif;\">шеи</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">) – при симптомах нарушения мозгового кровообращения; ЦДС вен нижних конечностей – при подозрении на венозную недостаточность, варикозное расширение вен, флеботромбоз.</span></span></p>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Подготовка пациента к проведению ультразвукового исследования</b></span></p>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Специальная подготовка требуется лишь при некоторых видах УЗИ</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\n\n<ul>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">на исследование органов мочевыделительной системы, предстательной железы пациенту необходимо приходить с максимально наполненным мочевым пузырем (выпить не менее 1 литра воды за час до исследования и не мочиться)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">так же следует поступить перед прохождением УЗИ органов малого таза (матка, яичники), если исследование предполагается проводить через переднюю брюшную стенку (наружным датчиком)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">особенно тщательно необходимо подготовиться к плановому УЗИ органов брюшной полости – значительное скопление газов в кишечнике крайне затрудняет исследование, поэтому за три дня до процедуры рекомендуется исключить из рациона бобовые, капусту, черный хлеб, молоко и др. продукты, усиливающие газообразование, принимать ферментные препараты, адсорбенты (активированный уголь) или др. средства против метеоризма, последний прием пищи должен быть не позднее 7 часов вечера накануне, исследование проводится натощак</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\n</li>\n 	<li>\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">плановое УЗИ молочных желез желательно проходить на 5-8 день менструального цикла, гинекологическое – в зависимости от цели исследования (для выявления эндометриоза – накануне менструации, при изучении процесса созревания фолликулов – на 5-й, 9-й и 14-17 дни цикла, в других случаях – на 7-10 день цикла).</span></span></p>\n</li>\n</ul>\n<p align=\"JUSTIFY\"><a name=\"section_4\"></a><a name=\"aswift_2_expand\"></a><a name=\"aswift_2_anchor\"></a><a name=\"section_5\"></a> <span style=\"font-family: Arial, serif;\">Несмотря на высокую информативность метода, результаты УЗИ должны трактоваться специалистом в комплексе с результатами других исследований и клинической картиной заболевания.</span></p>', 'УЗИ', '', 'inherit', 'closed', 'closed', '', '16-autosave-v1', '', '', '2017-12-13 08:14:49', '2017-12-13 05:14:49', '', 16, 'http://cmd-lyubertsy.ru/2017/12/13/16-autosave-v1/', 0, 'revision', '', 0),
(19, 1, '2017-12-13 08:23:44', '2017-12-13 05:23:44', '<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Ультразвуковое исследование</b></span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Ультразвуковое исследование</b></span> <span style=\"font-family: Arial, serif;\"><b>(УЗИ, сонография, ультрасонография, эхография)</b></span><span style=\"font-family: Arial, serif;\"> – современный аппаратный диагностический метод, основанный на регистрации и визуализации изменений ульразвукового сигнала, отражаемого от различных органов и тканей.</span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">В процессе исследования используется специальный датчик, одновременно излучающий ультразвуковые волны и принимающий отраженный сигнал – «эхо». При прохождении через различные по плотности ткани, границы органов, данный сигнал претерпевает определенные изменения, которые и фиксируются датчиком. Полученная информация перерабатывается компьютером в визуальное изображение на мониторе.</span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Преимущества метода</b></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">высокая информативность</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">относительно невысокая стоимость;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">неинвазивность (не требует нарушения целостности тканей);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">безболезненность;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">безопасность</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">возможность изучения как структуры, так и функции органов</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">возможность многократного повторения исследования без вреда для пациента.</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Перечисленные преимущества позволяют использовать данный метод для проведения скрининговых профилактических исследований с целью ранней диагностики, для уточнения предположительного диагноза, а также для динамического наблюдения за развитием заболевания, контроля эффективности лечения. УЗИ широко используется при ведении беременности, обследовании детей грудного возраста.</span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Ультразвуковым методом можно исследовать следующие органы и системы</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">органы брюшной полости (печень, желчный пузырь и желчевыводящие протоки, поджелудочная железа);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">мочевыделительная система (почки, мочеточники, мочевой пузырь);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">органы репродуктивной системы у женщин и мужчин (матка и яичники, фаллопиевы трубы, предстательная железа);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">молочные железы;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">щитовидная железа;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">головной мозг;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">сердце и сосуды;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">мягкие ткани.</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">С помощью ультразвука специалист получает, в первую очередь, информацию о строении органа</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">расположение, контуры, размер, соотношение анатомических структур, наличие аномалий</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">плотность, однородность тканей, наличие включений, конкрементов (камней);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">объемные образования (опухоли, кисты, абсцессы и др.).</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Кроме того, отдельные виды исследований с использованием ультразвука позволяют также оценить функцию изучаемого органа, например</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">при УЗИ сердца (эхокардиография) оцениваются особенности гемодинамики, полноценность работы сердечных клапанов, сократительная способность миокарда</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">ультразвуковое исследование сосудов позволяет не только обнаружить аневризмы, атеросклеротические бляшки и тромбы, но также (при использовании допплер-эффекта) измерить скорость, объем и др. параметры кровотока</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">под контролем УЗИ выполняются функциональные пробы – например, для исследования моторной функции желчного пузыря (пробный завтрак) и др.</span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Особенно востребован метод УЗИ в акушерстве и гинекологии</b></span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"><b>:</b></span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">диагностика причин бесплодия;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">диагностика беременности (в т.ч. внематочной), определение ее срока;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">наблюдение за течением беременности, выявление угрозы выкидыша и др. видов патологии;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">определение расположения плода в матке, выявление возможных аномалий развития, выяснение пола будущего ребенка (на современном этапе можно получать 3D</span></span><span style=\"font-family: Arial, serif;\">-изображение высокой четкости)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">раннее обнаружение новообразований в матке и яичниках, выявление эндометриоза, фибромиом, кист и пр.;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">выполнение некоторых лечебно-диагностических манипуляций под контролем УЗИ повышает их эффективность и безопасность.</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"><b>Дуплексное сканирование вен и артерий</b></span></span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"> – отдельный диагностический метод с использованием возможностей ультразвука. Современный вариант данного исследования называется цветовым дуплексным сканированием (ЦДС), или триплексным сканированием, т.к. в него входят три составляющие:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">подробная визуализация сосудов;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">допплерография (определение скорости кровотока и др. его параметров на основе допплер-эффекта – изменения частоты отраженного сигнала в зависимости от скоросте движения);</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">цветовое картирование – наглядное обозначение цветом особенностей гемодинамики на разных участках сосудистого русла (направление тока крови, турбулентность и т.д.).</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">Преимуществами метода, который уже стал “золотым стандартом”, являются безопасность, неинвазивность, высокая информативность и быстрота выполнения процедуры. С помощью ЦДС можно изучить расположение сосудов, их извитость, определить наличие сосудистых аномалий, выпячиваний или сужений, измерить толщину стенки и ширину просвета сосуда, обнаружить препятствия, мешающие свободному движению крови (атеросклеротические бляшки, тромбы). При исследовании вен определяется также состоятельность венозных клапанов.</span></span></p>\r\n<p align=\"JUSTIFY\"><a name=\"_GoBack\"></a><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">В зависимости от назначения врача исследуется определенная группа сосудов</span></span><span style=\"font-family: Arial, serif;\">.</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\"> Например, ЦДС брахиоцефальных артерий (сосудов головы и </span></span><span style=\"font-family: Arial, serif;\">шеи</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">) – при симптомах нарушения мозгового кровообращения; ЦДС вен нижних конечностей – при подозрении на венозную недостаточность, варикозное расширение вен, флеботромбоз.</span></span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><b>Подготовка пациента к проведению ультразвукового исследования</b></span></p>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">Специальная подготовка требуется лишь при некоторых видах УЗИ</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">:</span></span></p>\r\n\r\n<ul>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">на исследование органов мочевыделительной системы, предстательной железы пациенту необходимо приходить с максимально наполненным мочевым пузырем (выпить не менее 1 литра воды за час до исследования и не мочиться)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">так же следует поступить перед прохождением УЗИ органов малого таза (матка, яичники), если исследование предполагается проводить через переднюю брюшную стенку (наружным датчиком)</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\">особенно тщательно необходимо подготовиться к плановому УЗИ органов брюшной полости – значительное скопление газов в кишечнике крайне затрудняет исследование, поэтому за три дня до процедуры рекомендуется исключить из рациона бобовые, капусту, черный хлеб, молоко и др. продукты, усиливающие газообразование, принимать ферментные препараты, адсорбенты (активированный уголь) или др. средства против метеоризма, последний прием пищи должен быть не позднее 7 часов вечера накануне, исследование проводится натощак</span><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">;</span></span></p>\r\n</li>\r\n 	<li>\r\n<p align=\"JUSTIFY\"><span style=\"font-family: Arial, serif;\"><span lang=\"en-US\">плановое УЗИ молочных желез желательно проходить на 5-8 день менструального цикла, гинекологическое – в зависимости от цели исследования (для выявления эндометриоза – накануне менструации, при изучении процесса созревания фолликулов – на 5-й, 9-й и 14-17 дни цикла, в других случаях – на 7-10 день цикла).</span></span></p>\r\n</li>\r\n</ul>\r\n<p align=\"JUSTIFY\"><a name=\"section_4\"></a><a name=\"aswift_2_expand\"></a><a name=\"aswift_2_anchor\"></a><a name=\"section_5\"></a> <span style=\"font-family: Arial, serif;\">Несмотря на высокую информативность метода, результаты УЗИ должны трактоваться специалистом в комплексе с результатами других исследований и клинической картиной заболевания.</span></p>', 'УЗИ', '', 'inherit', 'closed', 'closed', '', '16-revision-v1', '', '', '2017-12-13 08:23:44', '2017-12-13 05:23:44', '', 16, 'http://cmd-lyubertsy.ru/2017/12/13/16-revision-v1/', 0, 'revision', '', 0),
