ps class=\"ymaps-2-1-56-placemark-overlay ymaps-2-1-56-user-selection-none\" unselectable=\"on\" style=\"z-index: 800000000; height: 0px; width: 0px; position: absolute; left: 371px; top: 335px;\"><ymaps><ymaps class=\"ymaps-2-1-56-islets_dot-icon-with-caption\"><ymaps class=\"ymaps-2-1-56-islets_dot-icon-with-caption__caption-block\"><ymaps class=\"ymaps-2-1-56-islets_icon-caption\" style=\"max-width: 188px;\">CMD Клиник</ymaps></ymaps><ymaps id=\"id_151318459445799362000\"><ymaps class=\"ymaps-2-1-56-svg-icon ymaps_https___api_maps_yandex_ru_2_1_56_1368768689891islands_dotIcon___1E98FF__1E98FF_34x41_1513184597035\" style=\"position: absolute; width: 34px; height: 41px; left: -11px; top: -38px;\"></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps><ymaps class=\"ymaps-2-1-56-searchpanel-pane\" style=\"width: 100%; top: 0px; left: 0px; position: absolute; z-index: 7811;\"><ymaps><ymaps class=\"ymaps-2-1-56-search ymaps-2-1-56-search_layout_panel ymaps-2-1-56-searchbox__panel-layout\"><ymaps class=\"ymaps-2-1-56-search__layout\"><ymaps id=\"id_151318459445799362032\"><ymaps><ymaps class=\"ymaps-2-1-56-searchbox__input-cell\"><ymaps class=\"ymaps-2-1-56-searchbox-input\"><ymaps class=\"ymaps-2-1-56-searchbox-input__icon\"></ymaps><input class=\"ymaps-2-1-56-searchbox-input__input\" placeholder=\"Адрес или объект\"><ymaps class=\"ymaps-2-1-56-searchbox-input__clear-button\"></ymaps></ymaps><ymaps class=\"ymaps-2-1-56-searchbox-list-button\"></ymaps></ymaps><ymaps class=\"ymaps-2-1-56-searchbox__button-cell\"><ymaps class=\"ymaps-2-1-56-searchbox-button ymaps-2-1-56-user-selection-none\" unselectable=\"on\"><ymaps class=\"ymaps-2-1-56-searchbox-button-text\">Найти</ymaps></ymaps></ymaps></ymaps></ymaps><ymaps class=\"ymaps-2-1-56-searchbox__fold-button-cell\"><ymaps class=\"ymaps-2-1-56-searchbox__fold-button\"><ymaps class=\"ymaps-2-1-56-searchbox__fold-button-icon\"></ymaps></ymaps></ymaps></ymaps><ymaps id=\"id_151318459445799362033\"><ymaps><ymaps class=\"ymaps-2-1-56-islets_serp-popup ymaps-2-1-56-islets__hidden\"><ymaps class=\"ymaps-2-1-56-islets_serp-popup__tail\"></ymaps><ymaps class=\"ymaps-2-1-56-islets_serp\" style=\"max-height: 600px;\"><ymaps id=\"id_151318459445799362034\"><ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps></ymaps>\n											</div>\n											\n											\n											<div class=\"col-md-5 text-left\">\n											<h1>Контакты</h1>\n											<p>\n											Россия, Московская область, 140000, г. Люберцы,\n											Комсомольский проспект, дом 16/2\n											</p>\n												<div class=\"row\">\n													<div class=\"col-md-6\">\n													<a href=\"tel:+74993754341\">+7 (499) 375-43-41</a>\n													</div>\n											\n													<div class=\"col-md-6\">\n													<a href=\"mailto:krasnayagorka.cmd@mbcon.ru\" class=\"text-right\">krasnayagorka.cmd@mbcon.ru&nbsp;</a>\n													</div>\n												</div>\n												<b>\n												<div class=\"row\">\n												\n													<div class=\"col-md-6\">\n													Понедельник-пятница<br>7.30-20.00\n													</div>\n													\n													<div class=\"col-md-3\">\n													Суббота<br>\n													7.30-19.00\n													</div>										\n													\n													<div class=\"col-md-3\">\n													Воскресенье<br>\n													7.30-17.00\n													</div>\n															\n												</div>\n												</b>	\n											<h6>Как добраться</h6>	\n											<h6 class=\"text-viol\">Общественным транспортом</h6>	\n											<p>\n											От станции “Люберцы-1” дойти до остановки общественного транспорта “Люберцы”. На автобусе № 7, либо маршрутном такси № 527 (Марусино), 527 (Самолет), 564 доехать до остановки “Магазин Пятерочка”\n											</p>	\n											<h6 class=\"text-viol\">Личным транспортом</h6>\n											<p>\n											От станции “Люберцы-1” выехать на дублер Комсомольского проспекта и далее двигаться прямо до дома № 16/2\n											</p>\n											\n											</div>\n\n											\n										</div>', 'Контакты', '', 'inherit', 'closed', 'closed', '', '64-autosave-v1', '', '', '2017-12-13 20:04:57', '2017-12-13 17:04:57', '', 64, 'http://cmd-lyubertsy.ru/2017/12/13/64-autosave-v1/', 0, 'revision', '', 0),
(67, 1, '2017-12-13 20:05:41', '2017-12-13 17:05:41', '										<div class=\"row\" >\r\n\r\n											\r\n											<div class=\"col-md-12 text-left\">\r\n											\r\n											<p>\r\n											Россия, Московская область, 140000, г. Люберцы,\r\n											Комсомольский проспект, дом 16/2\r\n											</p>\r\n												<div class=\"row\">\r\n													<div class=\"col-md-6\">\r\n													<a href=\"tel:+74993754341\">+7 (499) 375-43-41</a>\r\n													</div>\r\n											\r\n													<div class=\"col-md-6\">\r\n													<a href=\"mailto:krasnayagorka.cmd@mbcon.ru\" class=\"text-right\">krasnayagorka.cmd@mbcon.ru </a>\r\n													</div>\r\n												</div>\r\n												<b>\r\n												<div class=\"row\">\r\n												\r\n													<div class=\"col-md-6\">\r\n													Понедельник-пятница<br>7.30-20.00\r\n													</div>\r\n													\r\n													<div class=\"col-md-3\">\r\n													Суббота<br>\r\n													7.30-19.00\r\n													</div>										\r\n													\r\n													<div class=\"col-md-3\">\r\n													Воскресенье<br>\r\n													7.30-17.00\r\n													</div>\r\n															\r\n												</div>\r\n												</b>	\r\n											<h6>Как добраться</h6>	\r\n											<h6 class=\"text-viol\">Общественным транспортом</h6>	\r\n											<p>\r\n											От станции “Люберцы-1” дойти до остановки общественного транспорта “Люберцы”. На автобусе № 7, либо маршрутном такси № 527 (Марусино), 527 (Самолет), 564 доехать до остановки “Магазин Пятерочка”\r\n											</p>	\r\n											<h6 class=\"text-viol\">Личным транспортом</h6>\r\n											<p>\r\n											От станции “Люберцы-1” выехать на дублер Комсомольского проспекта и далее двигаться прямо до дома № 16/2\r\n											</p>\r\n											\r\n											</div>\r\n											<div class=\"col-md-12 \">\r\n<script type=\"text/javascript\" charset=\"utf-8\" async src=\"https://api-maps.yandex.ru/services/constructor/1.0/js